interface Plugin {
  start(): void
}

class App {
  private plugins: Plugin[] = []
  register(plugin: Plugin) { this.plugins.push(plugin) }
  run() { this.plugins.forEach(p => p.start()) }
}

interface Notifier { notify(evt: string): void }

class PaymentProcessor {
  constructor(private notifier: Notifier) {}
  process(amount: number) {
    // process payment
    this.notifier.notify('payment_processed')
  }
}

// Version A: application must drive engine tick
class EngineA {
  private tasks: (() => void)[] = []
  addTask(t: () => void) { this.tasks.push(t) }
  tick() { this.tasks.forEach(t => t()) }
}
const engineA = new EngineA()
engineA.addTask(() => console.log('task'))
// App must call engineA.tick() regularly

// Version B: engine runs and invokes registered tasks internally
class EngineB {
  private tasks: (() => void)[] = []
  register(t: () => void) { this.tasks.push(t) }
  start() { setInterval(() => this.tasks.forEach(t => t()), 1000) }
}
const engineB = new EngineB()
engineB.register(() => console.log('task'))
